style.css:
:root {
  /* Swap colors or the background image here */
  --my-bg-color: #06215c;
  --my-bg-image: url("data:image/png;base64,");
  --my-surface: rgba(7, 18, 48, 0.82);
  --my-surface-solid: rgba(7, 18, 48, 0.94);
  --my-surface-hover: rgba(24, 48, 108, 0.85);
  --my-border: rgba(145, 195, 255, 0.24);
  --my-text: #f3f7ff;
  --my-text-muted: #b6c8f0;
  --my-accent: #ff9ec7;
  --my-accent-alt: #7ce8ff;

  /* Override Google Material dark surface tokens */
  --gm3-sys-color-background: transparent !important;
  --gm3-sys-color-surface: var(--my-surface) !important;
  --gm3-sys-color-surface-container: var(--my-surface) !important;
  --gm3-sys-color-surface-container-low: var(--my-surface) !important;
  --gm3-sys-color-surface-container-high: var(--my-surface-solid) !important;
  --gm3-sys-color-surface-container-highest: var(--my-surface-solid) !important;
  --gm3-sys-color-on-background: var(--my-text) !important;
  --gm3-sys-color-on-surface: var(--my-text) !important;
  --gm3-sys-color-on-surface-variant: var(--my-text-muted) !important;
  --gm3-sys-color-outline: var(--my-border) !important;
  --gm3-sys-color-outline-variant: var(--my-border) !important;
  --gm3-sys-color-primary: var(--my-accent) !important;
  --mdc-theme-background: transparent !important;
  --mdc-theme-surface: var(--my-surface) !important;
  --mdc-theme-on-surface: var(--my-text) !important;
}

/* Fixed Pusheen starry background */
html,
body {
  background-color: var(--my-bg-color) !important;
  background-image: var(--my-bg-image) !important;
  background-position: center center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  image-rendering: pixelated !important;
  color: var(--my-text) !important;
}

/* Keep main layout wrappers transparent so the wallpaper shines through */
body > div,
main,
[role="main"] {
  background: transparent !important;
}

/* Top bar and left navigation drawer */
header,
[role="banner"] {
  background-color: var(--my-surface) !important;
  backdrop-filter: blur(12px) !important;
  border-bottom: 1px solid var(--my-border) !important;
  color: var(--my-text) !important;
}

nav,
aside,
[role="navigation"] {
  background-color: var(--my-surface-solid) !important;
  backdrop-filter: blur(14px) !important;
  border-right: 1px solid var(--my-border) !important;
  color: var(--my-text) !important;
}

/* Frosted dark glass for class cards, stream posts, menus, and popups */
ol > li,
article,
[role="dialog"],
[role="menu"],
[role="listbox"] {
  background-color: var(--my-surface) !important;
  backdrop-filter: blur(10px) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 14px !important;
  color: var(--my-text) !important;
}

/* Hover highlight on navigation links and menu options */
[role="navigation"] a:hover,
[role="menuitem"]:hover,
[role="option"]:hover {
  background-color: var(--my-surface-hover) !important;
}

/* Starlight typography and donut-pink links */
h1, h2, h3, h4, h5, h6,
p, label, td, th,
[role="main"] span,
[role="navigation"] span,
header span {
  color: var(--my-text) !important;
}

a {
  color: var(--my-accent) !important;
}

a:hover {
  color: var(--my-accent-alt) !important;
}

/* Dark inputs and comment boxes */
input,
textarea,
select,
[contenteditable="true"] {
  background-color: var(--my-surface-solid) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 10px !important;
}

input:focus,
textarea:focus,
[contenteditable="true"]:focus {
  border-color: var(--my-accent) !important;
  outline: none !important;
}

/* Make Google's dark icons match the light theme */
header svg,
nav svg,
[role="navigation"] svg,
[role="button"] svg {
  fill: currentColor !important;
  color: var(--my-text) !important;
}
